mapper.select:
SELECT t.environment_history_id AS environmentHistoryId, t.plan_id AS planId, t.measured_at AS measuredAt, t.temperature, t.humidity, t.co2, t.radiation, t.light, t.soil_temperature AS soilTemperature, t.soil_moisture AS soilMoisture, t.soil_ec AS soilEc, t.soil_ph AS soilPh FROM greenhouse_environment_history t JOIN cultivation_plan p ON p.plan_id = t.plan_id
WHERE p.member_id = #{memberId} AND t.plan_id = #{planId}
AND t.measured_at >= #{from}
AND t.measured_at < #{to}
ORDER BY t.measured_at DESC, t.environment_history_id DESC

SELECT t.issue_id AS issueId, t.plan_id AS planId, t.issue_type AS issueType, t.issue_message AS issueMessage, t.occurred_at AS occurredAt, t.issue_status AS issueStatus, t.issue_value AS issueValue, t.action_content AS actionContent, t.action_completed_at AS actionCompletedAt FROM greenhouse_issue t JOIN cultivation_plan p ON p.plan_id = t.plan_id
WHERE p.member_id = #{memberId} AND t.plan_id = #{planId}
AND t.occurred_at >= #{from}
AND t.occurred_at < #{to}
AND t.issue_type = #{type}
AND t.issue_status = #{status}
ORDER BY t.occurred_at DESC, t.issue_id DESC
